-- ----------------------------
-- Table structure for auditflow
-- ----------------------------
DROP TABLE IF EXISTS `auditflow`;
CREATE TABLE `auditflow`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `flowname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '流程名称',
  `stepnum` int NULL DEFAULT 1 COMMENT '审核步骤',
  `step` int NULL DEFAULT 1 COMMENT '步骤序号',
  `auditauthority` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '允许的审核人员ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `only_one`(`step`) USING BTREE COMMENT '保证步骤不重复'
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '审核流程' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of auditflow
-- ----------------------------

-- ----------------------------
-- Table structure for auditinfo
-- ----------------------------
DROP TABLE IF EXISTS `auditinfo`;
CREATE TABLE `auditinfo`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `flowname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '流程名称',
  `applyID` int NULL DEFAULT 0 COMMENT '对应的表主键',
  `stepnum` int NULL DEFAULT 1 COMMENT '审核总共步骤',
  `step` int NULL DEFAULT 1 COMMENT '步骤序号',
  `auditauthority` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '允许的审核人员ID（多个人员用逗号分隔）',
  `auditdate` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `userId` int NULL DEFAULT NULL COMMENT '审核人员ID',
  `UserName` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核人员姓名',
  `checkState` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核状态（审核中、通过、未通过）',
  `auditcomment` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  `submitflag` int NULL DEFAULT 0 COMMENT '提交标记',
  `addtime` date NULL DEFAULT NULL COMMENT '添加时间,此字段用于排序',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '审核流程' ROW_FORMAT = DYNAMIC;

