  `moneyAmount` double NULL DEFAULT 0 COMMENT '借入金额',
  `ratio` double NULL DEFAULT 0 COMMENT '贷款利率',
  `loanDate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '贷款发放日期',
  `loanDuring` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '贷款年限（年）',
  `mortgageGuarantee` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '抵押担保',
  `acountsName` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '打入账户',
  `bankNo` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '打入账号',
  `isEnd` int NULL DEFAULT 0 COMMENT '已还款标记(0为不结束,1是还款本金已经够了)',
