-- ----------------------------
-- Table structure for goodsorder
-- ----------------------------
DROP TABLE IF EXISTS `goodsorder`;
CREATE TABLE `goodsorder`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `ordersNo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '订单编号（UUID）',
  `orderDate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '日期',
  `customer` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '客户',
  `customerID` int NULL DEFAULT NULL COMMENT '客户ID',
  `landCarID` int NULL DEFAULT NULL COMMENT '陆运车辆ID',
  `landCarNo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆运车牌',
  `landDriverTel` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆运司机电话',
  `landDriverName` varchar(55) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆地司机姓名',
  `seaCarID` int NULL DEFAULT NULL COMMENT '海运车辆ID',
  `seaCarNo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运车牌',
  `seaDriverTel` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运司机电话',
  `seaDriverName` varchar(55) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运司机姓名',
  `checkUserId` int NULL DEFAULT NULL COMMENT '审核人编号',
  `checkState` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核状态（已审核、未审核）',
  `invoiceState` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '开票状态（未开票，部分开票，已开票）',
  `path` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '附件路径',
  `PaymentState` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '打款状态(申请中，已打款，未打款)',
  `landBankName` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆运银行户名',
  `landBankNo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆运银行账号',
  `seaBankName` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运银行户名',
  `seaBankNo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运银行账号',
  `receiveProof` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '收到条附件路径',
  `saleManager` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '销售经理',
  `fleet` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '车队',
  `isAdjusted` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '是否被调整单（ 是  否）',
  `adjustDate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '调整日期',
  `isAdjust` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '是否调整单（是  否）',
  `adjustOrderid` int NULL DEFAULT 0 COMMENT '原订单编号',
  `isedit` int NULL DEFAULT 1 COMMENT '是否可编辑',
  `customerIsInvoice` int NULL DEFAULT 0 COMMENT '客户开票个数,注意含义和名称不符,后期改造',
  `isSupplierInvoice` int NULL DEFAULT 0 COMMENT '供应商开票个数,注意含义和名称不符,后期改造',
  `cancelFlag` int NULL DEFAULT 0 COMMENT '作废标记',
  `comments` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `addtime` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '添加时间',
  `userId` int NULL DEFAULT NULL COMMENT '操作人员ID',
  `UserName` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作人员姓名',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `landFreight` double NULL DEFAULT NULL COMMENT '陆运费',
  `seaFreight` double NULL DEFAULT NULL COMMENT '海运费',
  `supplierNames` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '商家姓名集合',
  `allPayments` double NULL DEFAULT NULL COMMENT '总货款',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_delFlage_isAdjusted`(`isAdjusted`, `cancelFlag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '订单表' ROW_FORMAT = DYNAMIC;

