-- ----------------------------
DROP TABLE IF EXISTS `inventory`;
CREATE TABLE `inventory`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `storeHouseid` int NULL DEFAULT 0 COMMENT '仓库ID',
  `storeHouseName` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `storeDate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '入库日期',
  `stockNumber` int NULL DEFAULT 0 COMMENT '库存量（片数）',
  `supplier` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '供应商',
  `supplierId` int NULL DEFAULT NULL COMMENT '供应商ID',
  `levelID` int NULL DEFAULT NULL COMMENT '级别编码',
  `levelName` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '级别名称',
  `countingUnit` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `height` double NULL DEFAULT 0 COMMENT '厚度',
  `length` double NULL DEFAULT 0 COMMENT '长度',
  `width` double NULL DEFAULT 0 COMMENT '宽度',
  `pieces` int NULL DEFAULT NULL COMMENT '出厂片数',
  `piecesPerPack` int NULL DEFAULT NULL COMMENT '每包片数',
  `packs` int NULL DEFAULT NULL COMMENT '包数',
  `price` double NULL DEFAULT 0 COMMENT '出厂单价',
  `isIncludeTaxFactory` int NULL DEFAULT NULL COMMENT '出厂是否含税',
  `sundryCost` double NULL DEFAULT 0 COMMENT '杂费',
  `paymentFactory` double NULL DEFAULT 0 COMMENT '出厂货款',
  `paymentUnload` double NULL DEFAULT 0 COMMENT '卸货价',
  `isIncludeTaxSale` int NULL DEFAULT NULL COMMENT '销售是否含税（0不含税，1含税）',
  `payments` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '总货款',
  `landCarID` int NULL DEFAULT NULL COMMENT '陆运车辆ID',
  `landCarNo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆运车牌',
  `landDriverTel` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆运司机电话',
  `landDriverName` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '陆地司机姓名',
  `seaCarID` int NULL DEFAULT NULL COMMENT '海运车辆ID',
  `seaCarNo` varchar(550) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运车牌',
  `seaDriverTel` varchar(550) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运司机电话',
  `seaDriverName` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '海运司机姓名',
  `erro` double NULL DEFAULT 0 COMMENT '误差',
  `tonnage` double NULL DEFAULT 0 COMMENT '吨位',
  `landFreightPrice` double NULL DEFAULT 0 COMMENT '陆运费单价',
  `landFreight` double NULL DEFAULT 0 COMMENT '陆运费',
  `seaFreight` double NULL DEFAULT 0 COMMENT '海运费',
  `freight` double NULL DEFAULT 0 COMMENT '运费（海运费+陆运费）',
  `otherCost` double NULL DEFAULT 0 COMMENT '其他费用',
  `profit` double NULL DEFAULT 0 COMMENT '利润',
  `profitNoTax` double NULL DEFAULT 0 COMMENT '不含税利润',
  `actualPieces` int NULL DEFAULT NULL COMMENT '实际片数',
  `paymentsWithSundry` double NULL DEFAULT 0 COMMENT '总货款杂费',
  `additionalFees` double NULL DEFAULT 0 COMMENT '加费',
  `rebate` double NULL DEFAULT 0 COMMENT '返利金额',
  `customerCommission` double NULL DEFAULT 0 COMMENT '客户佣金',
  `comments` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `addtime` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '添加时间',
  `userId` int NULL DEFAULT NULL COMMENT '操作人员ID',
  `UserName` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作人员姓名',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delFlag` int NULL DEFAULT 0 COMMENT '删除标记',
  `showFlag` int NULL DEFAULT 0 COMMENT '订单仓库选择时是否显示（ 显示， 不显示）',
  `exWareHoustId` int NULL DEFAULT NULL COMMENT '二次入库对应的出库id',
  `goodsCompany` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '货物来源公司(本部或者海盛)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '库存' ROW_FORMAT = DYNAMIC;

