DROP TABLE IF EXISTS `invoicein`;
CREATE TABLE `invoicein`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `invoiceDate` varchar(55) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '开票日期',
  `invoiceObject` varchar(55) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '我方开票实体',
  `invoiceAmount` double NULL DEFAULT 0 COMMENT '开票金额',
  `companyType` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '对方公司类别（客户、供应商,其他）',
  `companyName` varchar(120) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '对方公司名称',
  `companyID` int NULL DEFAULT NULL COMMENT '对方公司ID',
  `invoiceCompanyName` varchar(120) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '票据单位名称',
  `ticketPoint` double NULL DEFAULT 0 COMMENT '票点',
  `ticketPointAmount` double NULL DEFAULT 0 COMMENT '票点金额（开票金额*票点）',
  `isOrderTax` int NULL DEFAULT 0 COMMENT '是否订单对应票点',
  `paymentReceipts` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '银行回执单',
  `invoiceAttachments` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '发票单',
  `comments` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `addtime` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '添加时间',
  `userId` int NULL DEFAULT NULL COMMENT '操作人员ID',
  `UserName` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作人员姓名',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delFlag` int NULL DEFAULT 0 COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '发票购入信息' ROW_FORMAT = DYNAMIC;

