-- ----------------------------
-- Table structure for orderdetail
-- ----------------------------
DROP TABLE IF EXISTS `orderdetail`;
CREATE TABLE `orderdetail`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `ordersNo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '订单编号（UUID）',
  `orderDate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '订单日期',
  `supplier` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '供应商',
  `supplierID` int NULL DEFAULT NULL COMMENT '供应商ID',
  `customer` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '客户',
  `customerID` int NULL DEFAULT NULL COMMENT '客户ID',
  `levelID` int NULL DEFAULT NULL COMMENT '级别编码',
  `levelName` varchar(80) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '级别名称',
  `countingUnit` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `height` double NULL DEFAULT 0 COMMENT '厚度',
  `length` double NULL DEFAULT 0 COMMENT '长度',
  `width` double NULL DEFAULT 0 COMMENT '宽度',
  `pieces` int NULL DEFAULT NULL COMMENT '出厂片数',
  `piecesPerPack` int NULL DEFAULT NULL COMMENT '每包片数',
  `packs` int NULL DEFAULT NULL COMMENT '包数',
  `price` double NULL DEFAULT NULL COMMENT '出厂单价',
  `isIncludeTaxFactory` int NULL DEFAULT NULL COMMENT '出厂是否含税',
  `sundryCost` double NULL DEFAULT NULL COMMENT '杂费',
  `paymentFactory` double NULL DEFAULT NULL COMMENT '出厂货款',
  `paymentUnload` double NULL DEFAULT NULL COMMENT '卸货价',
  `isIncludeTaxSale` int NULL DEFAULT NULL COMMENT '销售是否含税',
  `payments` double NULL DEFAULT NULL COMMENT '总货款',
  `erro` double NULL DEFAULT 0 COMMENT '误差',
  `tonnage` double NULL DEFAULT 0 COMMENT '吨位',
  `landFreightPrice` double NULL DEFAULT 0 COMMENT '陆运费单价',
  `landFreight` double NULL DEFAULT 0 COMMENT '陆运费',
  `seaFreight` double NULL DEFAULT 0 COMMENT '海运费',
  `freight` double NULL DEFAULT 0 COMMENT '总运费',
  `otherCost` double NULL DEFAULT NULL COMMENT '其他费用',
  `profit` double NULL DEFAULT NULL COMMENT '利润',
  `profitNoTax` double NULL DEFAULT NULL COMMENT '不含税利润',
  `actualPieces` int NULL DEFAULT NULL COMMENT '实际片数',
  `paymentsWithSundry` double NULL DEFAULT 0 COMMENT '总货款杂费',
  `additionalFees` double NULL DEFAULT 0 COMMENT '加费',
  `storeHouseID` int NULL DEFAULT 0 COMMENT '仓库ID',
  `storeHouseName` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `storeID` int NULL DEFAULT 0 COMMENT '仓库存储的货物ID',
  `logisticsProfit` double NULL DEFAULT 0 COMMENT '物流利润',
  `customerCommission` double NULL DEFAULT 0 COMMENT '客户佣金',
  `isAdjusted` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '是否被调整单（ 是  否）',
  `adjustDate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '调整日期',
  `cancelFlag` int NULL DEFAULT 0 COMMENT '作废标记',
  `comments` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `addtime` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '添加时间',
  `userId` int NULL DEFAULT NULL COMMENT '操作人员ID',
  `UserName` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '操作人员姓名',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderNo_cancelFlag`(`ordersNo`, `cancelFlag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '订单详情' ROW_FORMAT = DYNAMIC;

