-- ----------------------------
-- View structure for v_allinvoice
-- ----------------------------
DROP VIEW IF EXISTS `v_allinvoice`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_allinvoice` AS select `invoicein`.`id` AS `id`,NULL AS `ordersNo`,`invoicein`.`invoiceDate` AS `invoiceDate`,`invoicein`.`invoiceObject` AS `invoiceObject`,`invoicein`.`invoiceAmount` AS `invoiceAmount`,`invoicein`.`companyType` AS `companyType`,`invoicein`.`companyName` AS `companyName`,`invoicein`.`companyID` AS `companyID`,`invoicein`.`invoiceCompanyName` AS `invoiceCompanyName`,`invoicein`.`ticketPoint` AS `ticketPoint`,`invoicein`.`ticketPointAmount` AS `ticketPointAmount`,`invoicein`.`isOrderTax` AS `isOrderTax`,NULL AS `Supplier`,NULL AS `SupplierID`,NULL AS `customer`,NULL AS `CustomerID`,`invoicein`.`comments` AS `comments`,`invoicein`.`addtime` AS `addtime`,`invoicein`.`userId` AS `userId`,`invoicein`.`UserName` AS `UserName`,`invoicein`.`update_time` AS `update_time`,`invoicein`.`delFlag` AS `delFlag`,`invoicein`.`invoiceAmount` AS `purchaseInvoiceAmount`,`invoicein`.`ticketPoint` AS `ticketPointCost`,`invoicein`.`ticketPointAmount` AS `ticketPointCostAmount`,NULL AS `ticketPointIncome`,NULL AS `ticketPointIncomeAmount`,NULL AS `ticketPointDifference`,'invoicein' AS `tableName` from `invoicein` union select `invoiceout`.`id` AS `id`,NULL AS `ordersNo`,`invoiceout`.`invoiceDate` AS `invoiceDate`,`invoiceout`.`invoiceObject` AS `invoiceObject`,`invoiceout`.`invoiceAmount` AS `invoiceAmount`,`invoiceout`.`companyType` AS `companyType`,`invoiceout`.`companyName` AS `companyName`,`invoiceout`.`companyID` AS `companyID`,`invoiceout`.`invoiceCompanyName` AS `invoiceCompanyName`,`invoiceout`.`ticketPoint` AS `ticketPoint`,`invoiceout`.`ticketPointAmount` AS `ticketPointAmount`,`invoiceout`.`isOrderTax` AS `isOrderTax`,NULL AS `Supplier`,NULL AS `SupplierID`,NULL AS `customer`,NULL AS `CustomerID`,`invoiceout`.`comments` AS `comments`,`invoiceout`.`addtime` AS `addtime`,`invoiceout`.`userId` AS `userId`,`invoiceout`.`UserName` AS `UserName`,`invoiceout`.`update_time` AS `update_time`,`invoiceout`.`delFlag` AS `delFlag`,NULL AS `purchaseInvoiceAmount`,NULL AS `ticketPointCost`,NULL AS `ticketPointCostAmount`,`invoiceout`.`ticketPoint` AS `ticketPointIncome`,`invoiceout`.`ticketPointAmount` AS `ticketPointIncomeAmount`,NULL AS `ticketPointDifference`,'invoiceout' AS `tableName` from `invoiceout` union select `invoiceother`.`id` AS `id`,`invoiceother`.`ordersNo` AS `ordersNo`,`invoiceother`.`invoiceDate` AS `invoiceDate`,NULL AS `invoiceObject`,`invoiceother`.`invoiceAmount` AS `invoiceAmount`,NULL AS `companyType`,NULL AS `companyName`,NULL AS `companyID`,`invoiceother`.`invoiceCompanyName` AS `invoiceCompanyName`,`invoiceother`.`supplierTicketPoint` AS `ticketPoint`,`invoiceother`.`supplierPointAmount` AS `ticketPointAmount`,NULL AS `isOrderTax`,`invoiceother`.`Supplier` AS `Supplier`,`invoiceother`.`SupplierID` AS `SupplierID`,`invoiceother`.`customer` AS `customer`,`invoiceother`.`CustomerID` AS `CustomerID`,`invoiceother`.`comments` AS `comments`,`invoiceother`.`addtime` AS `addtime`,`invoiceother`.`userId` AS `userId`,`invoiceother`.`UserName` AS `UserName`,`invoiceother`.`update_time` AS `update_time`,`invoiceother`.`delFlag` AS `delFlag`,`invoiceother`.`invoiceAmount` AS `purchaseInvoiceAmount`,`invoiceother`.`supplierTicketPoint` AS `ticketPointCost`,`invoiceother`.`supplierPointAmount` AS `ticketPointCostAmount`,`invoiceother`.`customerTicketPoint` AS `ticketPointIncome`,`invoiceother`.`customerPointAmount` AS `ticketPointIncomeAmount`,(`invoiceother`.`customerPointAmount` - `invoiceother`.`supplierPointAmount`) AS `ticketPointDifference`,'invoiceother' AS `tableName` from `invoiceother`;

-- ----------------------------
-- View structure for v_orderfreight
-- ----------------------------
DROP VIEW IF EXISTS `v_orderfreight`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_orderfreight` AS select `orderdetail`.`ordersNo` AS `ordersNo`,sum(`orderdetail`.`landFreight`) AS `landFreight`,sum(`orderdetail`.`seaFreight`) AS `seaFreight`,sum(`orderdetail`.`freight`) AS `freight` from `orderdetail` where ((`orderdetail`.`cancelFlag` = 0) and (`orderdetail`.`isAdjusted` = 0)) group by `orderdetail`.`ordersNo`;

-- ----------------------------
-- View structure for 运费报表
-- ----------------------------
DROP VIEW IF EXISTS `运费报表`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `运费报表` AS select `orderfreight`.`CarNo` AS `车牌号`,`orderfreight`.`driverName` AS `司机姓名`,`orderfreight`.`otherBankNo` AS `司机银行账号`,sum((case when (`orderfreight`.`paymentState` = '已支付') then `orderfreight`.`moneyAmount` else 0 end)) AS `日支付总额`,sum((case when (`orderfreight`.`paymentState` = '未支付') then `orderfreight`.`moneyAmount` else 0 end)) AS `日未支付总额`,sum(`orderfreight`.`moneyAmount`) AS `日应付总额`,NULL AS `月支付总额`,NULL AS `月未支付总额`,NULL AS `月应付总额`,NULL AS `年支付总额`,NULL AS `年未支付总额`,NULL AS `年应付总额`,sum((case when ((cast(`orderfreight`.`payDate` as date) = (cast('2024-09-24' as date) - interval 1 day)) and (`orderfreight`.`paymentState` = '未支付')) then `orderfreight`.`moneyAmount` else 0 end)) AS `上一天未支付总额`,NULL AS `上一个月未支付总额`,NULL AS `上一年未支付总额` from `orderfreight` where (cast(`orderfreight`.`payDate` as date) = cast('2024-09-24' as date)) group by `orderfreight`.`CarNo`,`orderfreight`.`driverName`,`orderfreight`.`otherBankNo` union all select `orderfreight`.`CarNo` AS `车牌号`,`orderfreight`.`driverName` AS `司机姓名`,`orderfreight`.`otherBankNo` AS `司机银行账号`,NULL AS `日支付总额`,NULL AS `日未支付总额`,NULL AS `日应付总额`,sum((case when (`orderfreight`.`paymentState` = '已支付') then `orderfreight`.`moneyAmount` else 0 end)) AS `月支付总额`,sum((case when (`orderfreight`.`paymentState` = '未支付') then `orderfreight`.`moneyAmount` else 0 end)) AS `月未支付总额`,sum(`orderfreight`.`moneyAmount`) AS `月应付总额`,NULL AS `年支付总额`,NULL AS `年未支付总额`,NULL AS `年应付总额`,NULL AS `上一天未支付总额`,sum((case when ((date_format(`orderfreight`.`payDate`,'%Y-%m') = date_format((cast('2024-09-24' as date) - interval 1 month),'%Y-%m')) and (`orderfreight`.`paymentState` = '未支付')) then `orderfreight`.`moneyAmount` else 0 end)) AS `上一个月未支付总额`,NULL AS `上一年未支付总额` from `orderfreight` where (date_format(`orderfreight`.`payDate`,'%Y-%m') = date_format('2024-09-24','%Y-%m')) group by `orderfreight`.`CarNo`,`orderfreight`.`driverName`,`orderfreight`.`otherBankNo` union all select `orderfreight`.`CarNo` AS `车牌号`,`orderfreight`.`driverName` AS `司机姓名`,`orderfreight`.`otherBankNo` AS `司机银行账号`,NULL AS `日支付总额`,NULL AS `日未支付总额`,NULL AS `日应付总额`,NULL AS `月支付总额`,NULL AS `月未支付总额`,NULL AS `月应付总额`,sum((case when (`orderfreight`.`paymentState` = '已支付') then `orderfreight`.`moneyAmount` else 0 end)) AS `年支付总额`,sum((case when (`orderfreight`.`paymentState` = '未支付') then `orderfreight`.`moneyAmount` else 0 end)) AS `年未支付总额`,sum(`orderfreight`.`moneyAmount`) AS `年应付总额`,NULL AS `上一天未支付总额`,NULL AS `上一个月未支付总额`,sum((case when ((year(`orderfreight`.`payDate`) = year((cast('2024-09-24' as date) - interval 1 year))) and (`orderfreight`.`paymentState` = '未支付')) then `orderfreight`.`moneyAmount` else 0 end)) AS `上一年未支付总额` from `orderfreight` where (year(`orderfreight`.`payDate`) = year('2024-09-24')) group by `orderfreight`.`CarNo`,`orderfreight`.`driverName`,`orderfreight`.`otherBankNo`;

SET FOREIGN_KEY_CHECKS = 1;
